// Receive context including the two new note paths from the Orchestrator.
const ctx = $input.item.json;

return [{
  json: {
    new_notes:    ctx.new_notes    || [],   // array of { path, title, type }
    description:  ctx.description  || '',
    language:     ctx.language     || '',
    today:        new Date().toISOString().split('T')[0],
    vault_path:   $env.VAULT_PATH  || '/vault',
    ollama_url:   $env.OLLAMA_URL  || 'http://ollama:11434',
    ollama_model: $env.OLLAMA_MODEL|| 'deepseek-r1:7b'
  }
}];

// Build a compact index of existing notes: only .md files, strip vault prefix.
const vaultPath = $('Prepare Context').item.json.vault_path;
const files     = $input.all();

const mdFiles = files
  .map(f => f.json.fileName || f.json.name || f.json.path || '')
  .filter(n => n.endsWith('.md'))
  .map(n => n.replace(vaultPath + '/', ''));

const ctx = $('Prepare Context').item.json;

// Summarise existing notes into a short index string for the prompt.
const index = mdFiles.map(f => {
  // Extract a basename without extension for the wikilink label.
  const base = f.replace(/^.*\//, '').replace(/\.md$/, '');
  return `- [[${base}]] (${f})`;
}).join('\n');

return [{
  json: {
    ...ctx,
    existing_notes: mdFiles,
    index_string:   index
  }
}];

