const resp    = $input.item.json;
const rawText = resp.message?.content || resp.choices?.[0]?.message?.content || '[]';

// Strip any accidental markdown fences.
const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/,      '')
  .replace(/\s*```$/,      '')
  .trim();

let linkMap = [];
try {
  linkMap = JSON.parse(cleaned);
} catch(e) {
  // LLM returned something unparseable — degrade gracefully.
  linkMap = [];
}

// Flatten into individual items so the next node can iterate.
return linkMap.map(entry => ({
  json: {
    new_note_path: entry.new_note_path,
    links_to_add:  entry.links_to_add || []
  }
}));

// Append a ## Related Notes section if there are links to add.
const linkInfo   = $('Parse Link Map').item.json;
const fileResult = $input.item.json;

if (!linkInfo.links_to_add || linkInfo.links_to_add.length === 0) {
  // Nothing to do — pass through with no-op flag.
  return [{ json: { ...linkInfo, skip: true, note_content: fileResult.data } }];
}

const originalContent = fileResult.data || '';
const linkSection = `\n\n## Related Notes\n${linkInfo.links_to_add.map(l => `- ${l}`).join('\n')}\n`;

// Avoid duplicate section.
const updated = originalContent.includes('## Related Notes')
  ? originalContent
  : originalContent + linkSection;

return [{
  json: {
    ...linkInfo,
    skip:         false,
    note_content: updated
  }
}];
